def find_initial_cards(n, d, l):
    # Check if it's possible to reach the final card d with n cards and values between 1 and l
    for a in range(1, l + 1):
        for b in range(1, l + 1):
            cards = [a, b]
            while len(cards) < n:
                x, y = cards[-2], cards[-1]
                card = x - y if x - y > 0 else y - x
                cards.append(card)
            if len(cards) == n and cards[-1] == d and sum(cards) % d == 0:
                return ' '.join(map(str, cards))
    return -1

